insert into public.preguntas (curso, tema, pregunta, opciones, correcta, explicacion, inventada) values
('PIR 16', 'Pregunta 1', 'La enfermedad de Huntington es un trastorno hereditario que:', '["Sigue un patrón de transmisión autosómico recesivo.", "Sigue un patrón de transmisión autosómico dominante.", "Sigue un patrón de transmisión ligado al sexo.", "Sigue un patrón de transmisión multifactorial."]'::jsonb, 2, null, false),
('PIR 16', 'Pregunta 2', 'La enfermedad de Parkinson es un trastorno neurológico que se ha relacionado con la degeneración de las neuronas:', '["Del sistema mamilotalámico.", "Del sistema colinérgico del prosencéfalo basal.", "Del sistema nigroestriado.", "Del sistema serotoninérgico de los núcleos del rafe."]'::jsonb, 3, null, false),
('PIR 16', 'Pregunta 3', '¿Qué células localizadas en el sistema nervioso central rodean los capilares cerebrales y las membranas neuronales, participando en el suministro de nutrientes a las neuronas?:', '["Células de Schwann.", "Oligodendrocitos.", "La microglia.", "Astrocitos."]'::jsonb, 3, null, false),
('PIR 16', 'Pregunta 4', '¿Cómo se denomina la hormona que impide el desarrollo de los órganos sexuales internos femeninos?:', '["Testosterona.", "Dihidrotestosterona.", "Hormona inhibidora del sistema de Müller (hormona Antimülleriana).", "Estradiol."]'::jsonb, 2, null, false),
('PIR 16', 'Pregunta 5', 'La región de la corteza cerebral que aporta las claves sensoriales y motivacionales en los movimientos dirigidos a un objetivo es:', '["El área motora primaria.", "La corteza prefrontal ventromedial.", "La corteza prefrontal dorsolateral.", "La corteza parietal posterior."]'::jsonb, 3, null, false),
('PIR 16', 'Pregunta 6', 'El sistema neural que integra la mayoría de los estímulos relacionados con la sed osmótica y la volémica incluye al:', '["Locus coeruleus.", "Sustancia gris periacueductal.", "Núcleo preóptico mediano.", "Núcleo preóptico medial."]'::jsonb, 2, null, false),
('PIR 16', 'Pregunta 7', '¿Qué región cerebral se encuentra implicada en la inhibición y extinción de las respuestas emocionales condicionadas?:', '["La corteza prefrontal medial o ventromedial.", "La corteza parietal posterior.", "La sustancia gris periacueductal.", "El núcleo ventromedial del hipotálamo."]'::jsonb, 0, null, false),
('PIR 16', 'Pregunta 8', 'El síndrome que consiste en un cambio en la calidad de la voz que puede dar lugar a la aparición de un acento extranjero se denomina:', '["Aprosodia.", "Amusia.", "Hiperprosodia.", "Disprosodia."]'::jsonb, 3, null, false),
('PIR 16', 'Pregunta 9', 'Al evaluar un paciente neuropsicológicamente nos comunica su perplejidad, sorpresa y preocupación ante el movimiento de su brazo al coger el bolígrafo. Diremos que presenta:', '["Conducta de utilización.", "Síndrome de reduplicación.", "Síndrome de la mano ajena.", "Despersonalización."]'::jsonb, 2, null, false),
('PIR 16', 'Pregunta 10', 'Señale qué tipo de validez o fiabilidad hace referencia al hecho de que el contenido de una técnica de evaluación psicológica comprenda una muestra representativa del universo posible de las conductas que se pretende evaluar:', '["La validez criterial.", "La validez de contenido.", "La fiabilidad.", "La consistencia interna."]'::jsonb, 1, null, false),
('PIR 16', 'Pregunta 11', 'En la evaluación psicológica, la entrevista se considera semiestructurada cuando el entrevistador trabaja:', '["Con una secuencia de preguntas cerradas.", "Con una serie de preguntas abiertas prefijadas o un esquema definido.", "Con una secuencia de preguntas abiertas sin prefijar.", "Sin un esquema previo, en función de los problemas detectados."]'::jsonb, 1, null, false),
('PIR 16', 'Pregunta 12', 'Si utilizamos un criterio “alguedónico” como uno de los elementos definitorios de la existencia de una patología, estamos utilizando una variante de los criterios:', '["Estadísticos.", "Biológicos.", "Psicoanalíticos.", "Subjetivos."]'::jsonb, 3, null, false),
('PIR 16', 'Pregunta 13', 'La Técnica de la Rejilla, derivada de la Teoría de los constructos personales de Kelly, se considera, más propiamente, una prueba:', '["Proyectiva.", "Subjetiva.", "Psicométrica.", "Objetiva."]'::jsonb, 1, null, false),
('PIR 16', 'Pregunta 14', 'La entrevista de evaluación psicológica es un instrumento:', '["Necesariamente cuantificado.", "Necesariamente sistematizado.", "Necesariamente tipificado.", "Puede ser un instrumento ni cuantificado ni tipificado."]'::jsonb, 3, null, false),
('PIR 16', 'Pregunta 15', 'La importancia de la escucha activa en una entrevista se manifiesta en:', '["No dejar pausas en la conversación.", "Alargar el tiempo de la entrevista.", "Expresar inicialmente el propio acuerdo con el entrevistado.", "Mostrar que se ha comprendido cómo se siente el entrevistado."]'::jsonb, 3, null, false),
('PIR 16', 'Pregunta 16', 'El Cociente Intelectual (CI) se define como:', '["La razón entre la edad cronológica y la edad mental multiplicada por 100.", "La razón entre la edad mental y la edad cronológica multiplicada por 100.", "La multiplicación de la edad cronológica por la edad mental dividida por 100.", "El cociente entre la edad mental y la edad cronológica multiplicado por 10."]'::jsonb, 1, null, false),
('PIR 16', 'Pregunta 17', '¿Cuál de los siguientes aspectos NO constituye un parámetro relevante para que el ejercicio físico aeróbico resulte saludable?:', '["Una intensidad suficiente para que la frecuencia cardíaca se eleve a un determinado nivel.", "El tiempo o duración en el que la frecuencia cardíaca se mantiene a ese nivel.", "La frecuencia o número de días en que se realiza el ejercicio físico a la semana.", "La edad en que se inicia el ejercicio físico."]'::jsonb, 3, null, false),
('PIR 16', 'Pregunta 18', 'En la evaluación clínica puede surgir el problema de “los falsos positivos” que hace referencia a los sujetos:', '["Diagnosticados con un trastorno que realmente no padecen.", "No diagnosticados con un trastorno que realmente padecen.", "Que ocultan síntomas relativos al trastorno que padecen.", "Con alta deseabilidad social que tratan de dar una imagen positiva."]'::jsonb, 0, null, false),
('PIR 16', 'Pregunta 19', 'En la escala de inteligencia de Wechsler para niños (WISC III y WISC IV) los resultados en la prueba “búsqueda de símbolos” proporciona:', '["Un índice de velocidad de procesamiento.", "Un índice de memoria de trabajo.", "Un índice de organización perceptual.", "Un índice de comprensión verbal."]'::jsonb, 0, null, false),
('PIR 16', 'Pregunta 20', 'El método de evaluación en el que se recoge la información oral o escrita que una persona emite sobre sí misma se denomina:', '["Técnica psicofisiológica.", "Técnica proyectiva.", "Autoinforme.", "Observación."]'::jsonb, 2, null, false),
('PIR 16', 'Pregunta 21', 'El registro psicofisiológico es considerado una técnica objetiva de evaluación porque:', '["Respeta el carácter asituacional de los resultados.", "Las respuestas de la persona evaluada son registradas, codificadas y procesadas sin intermediación del evaluador.", "Registra parámetros que son estables e invariables a lo largo de amplios períodos de tiempo.", "La persona evaluada puede modificar sus respuestas según su voluntad."]'::jsonb, 1, null, false),
('PIR 16', 'Pregunta 22', 'La “Entrevista diagnóstica” (Diagnostic Interview Schedule, DIS), que proporciona información sobre el inicio, duración y actualidad de los síntomas, es un ejemplo de entrevista:', '["Estructurada.", "Semiestructurada.", "Motivacional.", "Abierta."]'::jsonb, 0, null, false),
('PIR 16', 'Pregunta 24', 'El inventario Multifásico de Personalidad de Minesota 2 (MMPI-2) evalúa:', '["Estilos de personalidad.", "Coherencia de la personalidad.", "Personalidad antisocial vs. altruista.", "Psicopatología general."]'::jsonb, 3, null, false),
('PIR 16', 'Pregunta 26', 'En la evaluación de la probabilidad de las conductas suicidas y autolíticas conviene:', '["Abordar el tema directamente solo cuando haya indicios de riesgo.", "Abordar el tema directamente, con preguntas explícitas, independientemente de la presencia o no de factores de riesgo.", "Abordar el tema indirectamente para que el paciente no se sienta intimidado.", "No abordar el tema, ya que hablar de suicidio incrementa la probabilidad de que la persona lo lleve a cabo."]'::jsonb, 1, null, false),
('PIR 16', 'Pregunta 28', '¿Cuáles son los instrumentos de evaluación de elección y preferentes para el diagnóstico de los trastornos de la eliminación?:', '["Cuestionarios como la Escala de Heces de Bristol.", "Autoinformes validados como el Cuestionario Clínico de Micción no Coordinada.", "Cuestionarios y autoinformes validados.", "Entrevistas y registros sistematizados de observación."]'::jsonb, 0, null, false),
('PIR 16', 'Pregunta 29', '¿Cuál de las siguientes es una de las principales dificultades que se encuentran al evaluar los trastornos de la conducta alimentaria?:', '["La negación o minimización del problema.", "La falta de empatía.", "La caquexia.", "La alextimia."]'::jsonb, 3, null, false),
('PIR 16', 'Pregunta 30', '¿Qué característica es aplicable a las escalas de evaluación conductual en niños, como el CBCL de Achenback?:', '["Normalmente la puntuación no se refiere a una puntuación normativa.", "No requiere de un informador.", "Proporciona impresiones del evaluador.", "Se pueden verificar si los cambios conductuales están dentro de los límites normales."]'::jsonb, 2, null, false),
('PIR 16', 'Pregunta 31', 'La valoración del equilibrio es un elemento indispensable de la evaluación del desarrollo psicomotor:', '["Del tono muscular.", "De la lateralidad.", "Del control postural.", "Del esquema corporal."]'::jsonb, 0, null, false),
('PIR 16', 'Pregunta 32', '¿Qué tarea realizará un niño al que se le evalúa mediante una técnica proyectiva de tipo expresivo?:', '["Realizará un dibujo a partir de una consigna verbal o escrita.", "Organizará un material dado a partir de una consigna.", "Emitirá una respuesta asociada a un estímulo.", "Narrará una historia a partir de la presentación de una lámina."]'::jsonb, 2, null, false),
('PIR 16', 'Pregunta 33', 'La finalización del proceso de evaluación psicológica en clínica implica un informe, el cual:', '["Basta con que se ofrezca de forma verbal sin ahondar en explicaciones sobre etiología y/o terapia que el paciente no vaya a comprender.", "Debe consistir, exclusivamente, en un documento escrito de cara a la futura posibilidad de ser requerido por autoridades sanitarias o jurídicas.", "Puede presentarse tanto de forma oral y/o escrita.", "En caso de presentarse por escrito, no se considerará un documento legal, ni como fuente de información de un sujeto, porque rompería el derecho a la intimidad."]'::jsonb, 2, null, false),
('PIR 16', 'Pregunta 34', 'En los procedimientos sociométricos aplicados a la infancia y la adolescencia ¿qué estrategia utiliza el número de elecciones y rechazos que recibe un individuo?:', '["Nominación por los iguales.", "Técnicas de “adivina quién”.", "Puntuación por los iguales.", "Escala de apreciación de los compañeros."]'::jsonb, 2, null, false),
('PIR 16', 'Pregunta 35', '¿Qué herramienta de evaluación sirve para explicar la topografía de la conducta de comer en un trastorno del comportamiento alimentario?:', '["Autoinforme de síntomas.", "Entrevista diagnóstica.", "Autorregistro.", "Cuestionario de comidas."]'::jsonb, 2, null, false),
('PIR 16', 'Pregunta 36', '¿A qué nivel de inteligencia corresponde una puntuación de 89 en la escala Wechsler para niños (WISC IV)?:', '["Medio alto.", "Medio.", "Medio bajo.", "Bajo."]'::jsonb, 2, null, false),
('PIR 16', 'Pregunta 37', '¿Qué proceso asociado a un trastorno de la escritura se evalúa con una prueba sobre capacidad para recuperar palabras?:', '["Procesos morfosintácticos.", "Procesos de composición de un texto.", "Procesos fonológicos.", "Procesos léxicos."]'::jsonb, 3, null, false),
('PIR 16', 'Pregunta 38', 'El Cuestionario de Calidad de Vida de la OMS “WHOQOL” (WHO, 1998) evalúa:', '["Está diseñado para evaluar la calidad de vida en enfermos mentales crónicos.", "El deterioro funcional.", "La calidad de vida medida objetivamente por índices de adaptación.", "La calidad de vida percibida, incluyendo áreas como la espiritualidad."]'::jsonb, 3, null, false),
('PIR 16', 'Pregunta 39', 'La evaluación de la personalidad se ha hecho desde diversos modelos y teorías. Desde las teorías factoriales, el test más representativo que ha inspirado el desarrollo de otros es:', '["Minnesota Multiphasic Personality Inventory, MMPI.", "Sixteen Personality Factor Questionnaire, 16PF.", "Gordon Personal Profile, GPP.", "Tennessee Self Concept Scale, TSCS."]'::jsonb, 1, null, false),
('PIR 16', 'Pregunta 40', 'La escala de rangos percentiles que habitualmente se emplea para comunicar los resultados de los test normativos constituyen una escala del tipo:', '["Nominal.", "Ordinal.", "Intervalo.", "Razón."]'::jsonb, 1, null, false),
('PIR 16', 'Pregunta 41', 'El coeficiente de fiabilidad de un test aumenta cuando:', '["Aumenta la variabilidad de la muestra.", "Disminuye el número de ítems.", "Aumenta la dimensionalidad.", "Disminuye su validez predictiva."]'::jsonb, 0, null, false),
('PIR 16', 'Pregunta 42', 'Entre los modelos de Teoría de Respuesta al Ítem (TRI) unidimensionales, el modelo logístico de un parámetro (Modelo de Rasch) se caracteriza por asumir que los ítems difieren en su nivel de dificultad (parámetro b) y:', '["El parámetro a=0 y el parámetro c=0.", "El parámetro a=1,7 y el parámetro c=0.", "El parámetro a es constante y el parámetro c=1,7.", "El parámetro a es constante y el parámetro c=0."]'::jsonb, 3, null, false),
('PIR 16', 'Pregunta 43', 'La sensibilidad de una prueba psicométrica empleada con fines de diagnóstico viene dada por:', '["El número de clasificaciones correctas hechas mediante la prueba.", "La proporción de casos correctamente detectados por la prueba.", "La proporción de casos incorrectamente detectados por la prueba.", "El número de casos que la prueba deja de detectar."]'::jsonb, 1, null, false),
('PIR 16', 'Pregunta 44', '¿Cuál de los siguientes es un supuesto que debe cumplirse para la aplicación de la prueba de chi-cuadrado de independencia en una tabla de contingencia:', '["Que exista un igual número de filas que de columnas.", "Que las variables estén medidas en escala ordinal.", "Que no haya más de un 20% de frecuencias esperadas inferiores a 5.", "Que las frecuencias esperadas sean iguales a las frecuencias empíricas."]'::jsonb, 2, null, false),
('PIR 16', 'Pregunta 45', 'En un diagrama de cajas (Box-Plot), la caja central representa:', '["El 100% de los casos.", "El 75% central de los casos.", "El 50% central de los casos.", "El 25% central de los casos."]'::jsonb, 2, null, false),
('PIR 16', 'Pregunta 47', 'Con relación al tipo de regla de asignación utilizada en los diseños de investigación, indique cuál de las siguientes afirmaciones es CORRECTA:', '["En un diseño pretest-postest con grupo de control no equivalente, la regla de asignación utilizada es no aleatoria pero conocida.", "En un diseño de discontinuidad de la regresión, la regla de asignación utilizada es no aleatoria pero conocida.", "En un diseño simple de series temporales interrumpidas, la regla de asignación utilizada es no aleatoria pero conocida.", "En un diseño de medidas totalmente repetidas, la regla de asignación utilizada es no aleatoria pero conocida."]'::jsonb, 1, null, false),
('PIR 16', 'Pregunta 48', 'En lo que respecta a las características de los diseños de investigación y a las técnicas de análisis asociadas a los mismos, indique cuál de las siguientes afirmaciones es CORRECTA:', '["En el diseño de bloques aleatorios se lleva a cabo una restricción a la aleatorización, de modo que los tratamientos se asignan aleatoriamente a los sujetos en función del bloque al que pertenecen.", "En los diseños de medidas totalmente repetidas, además de la homocedasticidad, es necesario garantizar el supuesto de esfericidad para poder utilizar pruebas paramétricas.", "En un diseño factorial AxB, cuando los resultados indican que tanto los efectos principales como el de la interacción son estadísticamente significativos, deben interpretarse en primer lugar los efectos principales y posteriormente el efecto de interacción.", "En los diseños multigrupos aleatorios, la presencia de interacción entre variables puede interpretarse como un efecto moderador."]'::jsonb, 0, null, false),
('PIR 16', 'Pregunta 49', 'En lo que respecta al uso de la aleatorización como regla de asignación, indique cuál de las siguientes afirmaciones es CORRECTA:', '["Los diseños experimentales y cuasi-experimentales se caracterizan por utilizar, como técnica de control, la asignación aleatoria de los sujetos a los tratamientos.", "La aleatorización o utilización de una regla de asignación aleatoria es la técnica de control más importante de los diseños experimentales debido a que su efectividad es independiente del tamaño muestral.", "Todos los diseños, tanto los intersujeto como los intrasujeto, deben incorporar la regla de asignación aleatoria para ser considerados diseños experimentales.", "La aleatorización, como técnica de equilibración, es una estrategia de control que persigue reducir el sesgo de selección."]'::jsonb, 1, null, false),
('PIR 16', 'Pregunta 50', 'Los aspectos del autoconcepto de una persona que están basados en su pertenencia a grupos se denomina:', '["Identidad social.", "Colectivismo.", "Autoestima.", "Endogrupo."]'::jsonb, 0, null, false),
('PIR 16', 'Pregunta 51', 'El denominado “sesgo de correspondencia” consiste en la tendencia a:', '["Responder positivamente ante las conductas altruistas.", "Encontrar semejanzas en la conducta de diferentes sujetos.", "Atribuir los comportamientos a las disposiciones internas de los sujetos.", "Explicar las conductas a partir de estímulos previos."]'::jsonb, 2, null, false),
('PIR 16', 'Pregunta 52', 'Cuando el comportamiento de una persona persigue evitar el rechazo del grupo, se produce el proceso denominado:', '["Influencia social informativa.", "Influencia social normativa.", "Fenómeno de dilución.", "Ilusión del Mundo Justo."]'::jsonb, 1, null, false),
('PIR 16', 'Pregunta 53', 'Una táctica o efecto de persuasión consistente en conseguir que un sujeto acceda a una petición costosa, haciendo que acceda antes a una petición de bajo coste, se denomina:', '["De la bola baja.", "De reducción de tensión.", "De la puerta en la cara.", "Del pie en la puerta."]'::jsonb, 3, null, false),
('PIR 16', 'Pregunta 54', 'El enfoque del liderazgo que se basa en el intercambio de recompensas entre el líder (agente de influencia) y sus seguidores se denomina:', '["Liderazgo transformacional.", "Modelo de liderazgo de contingencia.", "Liderazgo transaccional.", "Liderazgo carismático."]'::jsonb, 2, null, false),
('PIR 16', 'Pregunta 55', 'La aparición del denominado “Pensamiento grupal”, según modelo propuesto por Janis, se ve favorecida por:', '["El alto autoconcepto individual.", "La heterogeneidad del grupo.", "El liderazgo directivo o falta de tradición de un liderazgo imparcial.", "La trayectoria previa de éxito del grupo."]'::jsonb, 2, null, false),
('PIR 16', 'Pregunta 56', 'Cuando el discurso de la persona se caracteriza por un patrón de habla espontánea en el que las ideas se escabullen unas de otras, se dicen cosas yuxtaponiéndolas y falta una adecuada conexión entre frases o ideas, hablamos de:', '["Descarrilamiento.", "Tangencialidad.", "Habla adireccional.", "Alogia."]'::jsonb, 0, null, false),
('PIR 16', 'Pregunta 57', 'La circunstancialidad del pensamiento se caracteriza porque:', '["Se acompaña a menudo de pasividad motora, indiferencia afectiva y/o ausencia de motivación para actuar.", "Las conexiones entre pensamientos sucesivos se establecen, en muchos casos, al azar o en función de la semejanza de sonidos entre palabras, o por refranes, etc.", "Se produce una disminución significativa en la producción de pensamientos e imágenes mentales, de tal manera que el pensamiento se vuelve lento y trabajoso.", "La finalidad del pensamiento nunca se pierde y éste alcanza su meta pero progresa lentamente con multitud de detalles irrelevantes y excesivos paréntesis."]'::jsonb, 3, null, false),
('PIR 16', 'Pregunta 58', 'A los movimientos musculares en forma de contracciones violentas e incontrolables de la musculatura voluntaria que se manifiestan en uno o varios grupos musculares o bien de forma generalizada en todo el cuerpo, se les denomina:', '["Compulsiones.", "Convulsiones.", "Tics.", "Bradicinesias."]'::jsonb, 1, null, false),
('PIR 16', 'Pregunta 59', 'Cuando un recuerdo no es experimentado como tal, sino que, por el contrario, se experimenta como vivido por primera vez como una experiencia original, se denomina:', '["Criptoamnesia.", "“Déjà vu”.", "“Jamais vu”.", "Pseudología."]'::jsonb, 0, null, false),
('PIR 16', 'Pregunta 60', 'El síndrome de “Gilles de la Tourette” es un trastorno de tics que:', '["Afecta fundamentalmente a las mujeres.", "Se suele iniciar a partir de la adolescencia.", "Puede conllevar la manifestación de coprolalia.", "Se asocia a la enfermedad de Huntington."]'::jsonb, 2, null, false),
('PIR 16', 'Pregunta 61', 'Las contracciones musculares localizadas en los músculos del cuello que obligan al individuo a flexionarlo y extenderlo (espasmos salutatorios de Salaam) se presentan asociadas a:', '["El Alzheimer.", "La esquizofrenia.", "Ciertas profesiones como escribientes o violinistas.", "El pequeño mal de la epilepsia o lesiones del hipotálamo."]'::jsonb, 3, null, false),
('PIR 16', 'Pregunta 62', 'La “Disfemia tónica” es:', '["Un bloqueo intenso al inicio del discurso que el sujeto vence por la fuerza.", "Pequeños espasmos que provocan la repetición de fonemas a lo largo del discurso.", "Una amnesia permanente o temporal del lenguaje expresivo.", "Una dificultad para utilizar correctamente las relaciones gramaticales y sus reglas."]'::jsonb, 0, null, false),
('PIR 16', 'Pregunta 63', 'La capacidad para codificar semánticamente la información se encuentra deteriorada en los enfermos de:', '["Parkinson.", "Alzheimer.", "Esclerosis múltiple.", "Huntington."]'::jsonb, 1, null, false),
('PIR 16', 'Pregunta 64', 'A la hora de evaluar las habilidades sociales, si nos centramos en los elementos paralingüísticos, prestaremos atención a:', '["La expresión facial.", "El tono de voz.", "El sentido del humor de la conversación.", "El contacto ocular."]'::jsonb, 1, null, false),
('PIR 16', 'Pregunta 65', 'Cuando observamos en una persona un trastorno psicomotor que le dificulta llevar a cabo actividades propositivas que exijan secuenciar y coordinar ordenadamente una serie de movimientos (p. ej. abrocharse los botones) podemos hablar de:', '["Estereotipias.", "Discinesias.", "Dismimias.", "Apraxias."]'::jsonb, 3, null, false),
('PIR 16', 'Pregunta 66', 'La “laguna temporal” se caracteriza porque:', '["Es una alteración patológica de la memoria típica en los pacientes con Síndrome de Korsakoff.", "Es una alteración que ocurre independientemente del nivel de habilidad del sujeto en la tarea que está realizando.", "No se presenta desorientación persistente espacio-temporal.", "El sujeto registra los sucesos que funcionan como marcadores de tiempo, pero posteriormente no los puede recuperar."]'::jsonb, 2, null, false),
('PIR 16', 'Pregunta 67', 'Las dismegalopsias se caracterizan porque:', '["Son una modalidad de alucinaciones visuales.", "Son imágenes patológicas denominadas pseudopercepciones.", "Son alteraciones del espectro de los síntomas megalomaníacos.", "Son distorsiones perceptivas."]'::jsonb, 3, null, false),
('PIR 16', 'Pregunta 68', 'Las alucinaciones funcionales se caracterizan porque:', '["Los estímulos procedentes de un objeto externo se combinan con una imagen mental dando lugar a una falsa interpretación de la realidad.", "Se produce una percepción incorrecta de un estímulo externo por lo que algunos autores no la consideran como una verdadera alucinación sino como una forma especial de ilusión/distorsión.", "Son fenómenos mórbidos que solo se presentan en poblaciones con trastornos cerebrales.", "Un estímulo perteneciente a una modalidad sensorial, que es correctamente percibido, produce y se superpone a una alucinación en la misma modalidad sensorial que aparece y desaparece con ellos."]'::jsonb, 3, null, false),
('PIR 16', 'Pregunta 70', 'El Síndrome Amnésico se caracteriza porque:', '["Los afectados presentan déficits generalizados en pruebas de memoria operativa.", "Afecta fundamentalmente a la memoria implícita más que a la explícita.", "Afecta a la memoria semántica, pero no a la episódica.", "Afecta fundamentalmente a la memoria anterógrada."]'::jsonb, 3, null, false),
